#[derive(Debug, Clone, PartialEq)]
pub struct Link {
    pub ridden_entity_id: i64,
    pub rider_entity_id: i64,
    pub r#type: u8,
    pub immediate: bool,
    pub rider_initiated: bool,
    pub angular_velocity: f32,
}
impl Link {
    pub fn read(r: &mut &[u8]) -> Result<Self> {
        let f_ridden_entity_id = (|| -> Result<_> { Ok(read_zigzag64(r)?) })()
            .map_err(|e| e.at("Link.ridden_entity_id"))?;
        let f_rider_entity_id = (|| -> Result<_> { Ok(read_zigzag64(r)?) })()
            .map_err(|e| e.at("Link.rider_entity_id"))?;
        let f_type = (|| -> Result<_> { Ok(read_u8(r)?) })().map_err(|e| e.at("Link.type"))?;
        let f_immediate =
            (|| -> Result<_> { Ok(read_bool(r)?) })().map_err(|e| e.at("Link.immediate"))?;
        let f_rider_initiated =
            (|| -> Result<_> { Ok(read_bool(r)?) })().map_err(|e| e.at("Link.rider_initiated"))?;
        let f_angular_velocity =
            (|| -> Result<_> { Ok(read_lf32(r)?) })().map_err(|e| e.at("Link.angular_velocity"))?;
        Ok(Self {
            ridden_entity_id: f_ridden_entity_id,
            rider_entity_id: f_rider_entity_id,
            r#type: f_type,
            immediate: f_immediate,
            rider_initiated: f_rider_initiated,
            angular_velocity: f_angular_velocity,
        })
    }
    pub fn write(&self, w: &mut BytesMut) {
        write_zigzag64(w, self.ridden_entity_id);
        write_zigzag64(w, self.rider_entity_id);
        write_u8(w, self.r#type);
        write_bool(w, self.immediate);
        write_bool(w, self.rider_initiated);
        write_lf32(w, self.angular_velocity);
    }
}

