#[derive(Debug, Clone, PartialEq)]
pub struct Rotation {
    pub yaw: f32,
    pub pitch: f32,
    pub head_yaw: f32,
}
impl Rotation {
    pub fn read(r: &mut &[u8]) -> Result<Self> {
        let f_yaw = (|| -> Result<_> { Ok((read_u8(r)? as f32 * (360.0 / 256.0))) })()
            .map_err(|e| e.at("Rotation.yaw"))?;
        let f_pitch = (|| -> Result<_> { Ok((read_u8(r)? as f32 * (360.0 / 256.0))) })()
            .map_err(|e| e.at("Rotation.pitch"))?;
        let f_head_yaw = (|| -> Result<_> { Ok((read_u8(r)? as f32 * (360.0 / 256.0))) })()
            .map_err(|e| e.at("Rotation.head_yaw"))?;
        Ok(Self {
            yaw: f_yaw,
            pitch: f_pitch,
            head_yaw: f_head_yaw,
        })
    }
    pub fn write(&self, w: &mut BytesMut) {
        write_u8(w, (self.yaw / (360.0 / 256.0)) as i32 as u8);
        write_u8(w, (self.pitch / (360.0 / 256.0)) as i32 as u8);
        write_u8(w, (self.head_yaw / (360.0 / 256.0)) as i32 as u8);
    }
}

