#[derive(Debug, Clone, PartialEq)]
pub struct TransactionUseItem {
    pub action_type: TransactionUseItemActionType,
    pub trigger_type: TransactionUseItemTriggerType,
    pub block_position: BlockCoordinates,
    pub face: u8,
    pub hotbar_slot: i32,
    pub hand: TransactionUseItemHand,
    pub held_item: ItemV4,
    pub player_pos: Vec3f,
    pub click_pos: Vec3f,
    pub block_runtime_id: u32,
    pub client_prediction: TransactionUseItemClientPrediction,
    pub client_cooldown_state: TransactionUseItemClientCooldownState,
}
impl TransactionUseItem {
    pub fn read(r: &mut &[u8]) -> Result<Self> {
        let f_action_type = (|| -> Result<_> { Ok(TransactionUseItemActionType::read(r)?) })()
            .map_err(|e| e.at("TransactionUseItem.action_type"))?;
        let f_trigger_type = (|| -> Result<_> { Ok(TransactionUseItemTriggerType::read(r)?) })()
            .map_err(|e| e.at("TransactionUseItem.trigger_type"))?;
        let f_block_position = (|| -> Result<_> { Ok(BlockCoordinates::read(r)?) })()
            .map_err(|e| e.at("TransactionUseItem.block_position"))?;
        let f_face =
            (|| -> Result<_> { Ok(read_u8(r)?) })().map_err(|e| e.at("TransactionUseItem.face"))?;
        let f_hotbar_slot = (|| -> Result<_> { Ok(read_zigzag32(r)?) })()
            .map_err(|e| e.at("TransactionUseItem.hotbar_slot"))?;
        let f_hand = (|| -> Result<_> { Ok(TransactionUseItemHand::read(r)?) })()
            .map_err(|e| e.at("TransactionUseItem.hand"))?;
        let f_held_item = (|| -> Result<_> { Ok(ItemV4::read(r)?) })()
            .map_err(|e| e.at("TransactionUseItem.held_item"))?;
        let f_player_pos = (|| -> Result<_> { Ok(Vec3f::read(r)?) })()
            .map_err(|e| e.at("TransactionUseItem.player_pos"))?;
        let f_click_pos = (|| -> Result<_> { Ok(Vec3f::read(r)?) })()
            .map_err(|e| e.at("TransactionUseItem.click_pos"))?;
        let f_block_runtime_id = (|| -> Result<_> { Ok(read_varint(r)?) })()
            .map_err(|e| e.at("TransactionUseItem.block_runtime_id"))?;
        let f_client_prediction =
            (|| -> Result<_> { Ok(TransactionUseItemClientPrediction::read(r)?) })()
                .map_err(|e| e.at("TransactionUseItem.client_prediction"))?;
        let f_client_cooldown_state =
            (|| -> Result<_> { Ok(TransactionUseItemClientCooldownState::read(r)?) })()
                .map_err(|e| e.at("TransactionUseItem.client_cooldown_state"))?;
        Ok(Self {
            action_type: f_action_type,
            trigger_type: f_trigger_type,
            block_position: f_block_position,
            face: f_face,
            hotbar_slot: f_hotbar_slot,
            hand: f_hand,
            held_item: f_held_item,
            player_pos: f_player_pos,
            click_pos: f_click_pos,
            block_runtime_id: f_block_runtime_id,
            client_prediction: f_client_prediction,
            client_cooldown_state: f_client_cooldown_state,
        })
    }
    pub fn write(&self, w: &mut BytesMut) {
        self.action_type.write(w);
        self.trigger_type.write(w);
        self.block_position.write(w);
        write_u8(w, self.face);
        write_zigzag32(w, self.hotbar_slot);
        self.hand.write(w);
        self.held_item.write(w);
        self.player_pos.write(w);
        self.click_pos.write(w);
        write_varint(w, self.block_runtime_id);
        self.client_prediction.write(w);
        self.client_cooldown_state.write(w);
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum TransactionUseItemActionType {
    ClickBlock,
    ClickAir,
    BreakBlock,
    Attack,
    Unknown(i64),
}
impl TransactionUseItemActionType {
    pub fn from_raw(v: i64) -> Self {
        match v {
            0 => Self::ClickBlock,
            1 => Self::ClickAir,
            2 => Self::BreakBlock,
            3 => Self::Attack,
            v => Self::Unknown(v),
        }
    }
    pub fn to_raw(self) -> i64 {
        match self {
            Self::ClickBlock => 0,
            Self::ClickAir => 1,
            Self::BreakBlock => 2,
            Self::Attack => 3,
            Self::Unknown(v) => v,
        }
    }
    pub fn read(r: &mut &[u8]) -> Result<Self> {
        let v = Self::from_raw(read_zigzag32(r)? as i64);
        if let Self::Unknown(value) = v {
            crate::strict::note(crate::strict::Leniency::UnknownEnum {
                ty: "TransactionUseItemActionType",
                value,
            });
        }
        Ok(v)
    }
    pub fn write(&self, w: &mut BytesMut) {
        write_zigzag32(w, self.to_raw() as i32)
    }
}

